using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Windows.Forms;
namespace NightLens {
static class V2Tests {
    static IEnumerable<Control> Walk(Control root){foreach(Control c in root.Controls){yield return c;foreach(var child in Walk(c))yield return child;}}
    static void Snapshot(Form form,string path){form.Show();Application.DoEvents();using(var bmp=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bmp,new Rectangle(Point.Empty,bmp.Size));bmp.Save(path,System.Drawing.Imaging.ImageFormat.Png);}}
    public static void Run(Forecast forecast,DateTime now,string[] args,List<string> log){Action<bool,string> check=(ok,message)=>{if(!ok)throw new Exception(message);log.Add("PASS: "+message);};var s=new Settings{WindowsLocation=false};var catalogs=CatalogLibrary.Available();
        check(catalogs.Count>=4,"Four independent catalog files discovered");foreach(var c in catalogs){check(c.Error=="",c.Key+" parses without a catalog error");log.Add("CATALOG: "+c.Key+" — "+c.Rows+" source records; "+c.Targets.Count+" coordinate-valid targets; "+c.Skipped+" unplannable records");}
        check(catalogs.Single(c=>c.Key=="Messier.csv").Rows==110,"All 110 Messier source entries are included");check(catalogs.Where(c=>c.Key=="NGC.csv"||c.Key=="IC.csv").Sum(c=>c.Rows)==13970,"All 13970 downloaded NGC/IC records are retained");string notice;var all=CatalogLibrary.Load(s,out notice);check(all.Count>13000&&notice=="","More than 13000 unique catalog objects available offline");check(all.Select(x=>x.Canonical).Distinct(StringComparer.OrdinalIgnoreCase).Count()==all.Count,"Cross-catalog canonical identifiers are deduplicated");
        s.EnabledCatalogs=new List<string>{"Messier.csv"};s.IncludeSolar=false;var messier=CatalogLibrary.Load(s,out notice);check(messier.Count==110,"Catalog selection restricts library to Messier entries");var watch=System.Diagnostics.Stopwatch.StartNew();var night=new Night(s,forecast,now);watch.Stop();check(night.Picks.All(x=>!x.Target.Body.HasValue&&x.Target.CatalogName=="Messier"),"Disabled catalogs and solar-system objects cannot enter recommendations");s.EnabledCatalogs.Clear();var empty=new Night(s,forecast,now);check(empty.Picks.Count==0,"Empty catalog selection produces no hidden fallback targets");
        var parsed=CatalogLibrary.Parse("Name,Type,RAHours,DecDegrees,MajorArcmin,MinorArcmin,Magnitude,CanonicalId\r\n\"Example, quoted\",Galaxy,1.25,-20,5,3,9,Example-1\r\nBad,Galaxy,25,0,1,1,10,Bad\r\nUnknown size,Nebula,2,30,,,11,Unknown","Custom.csv");check(parsed.Targets.Count==2&&parsed.Skipped==1&&parsed.Targets[0].Name=="Example, quoted","Custom CSV handles quoted commas, validation and missing sizes");check(parsed.Targets[1].Major==0,"Missing angular dimensions remain unknown");s.EnabledCatalogs=new List<string>{"Missing.csv"};CatalogLibrary.Load(s,out notice);check(notice.Contains("missing"),"Missing selected catalogs are reported explicitly");
        s=new Settings{WindowsLocation=false};watch.Restart();night=new Night(s,forecast,now);watch.Stop();check(watch.Elapsed.TotalSeconds<15,"Full catalog recommendation calculation completes in under 15 seconds");log.Add("PERFORMANCE: full catalog ranking "+watch.Elapsed.TotalMilliseconds.ToString("0")+" ms");check(night.Picks.Count<=3,"Recommendations are limited to three for the night");
        string folder=Path.GetDirectoryName(args[3]);using(var form=new LocationForm(s)){Snapshot(form,Path.Combine(folder,"Location preview.png"));CheckLayout(form,check);check(Walk(form).OfType<Button>().Any(b=>b.Text=="Save location"&&b.Visible),"Location Save button is visible");}using(var form=new EquipmentForm(s)){Snapshot(form,Path.Combine(folder,"Equipment preview.png"));CheckLayout(form,check);check(!Walk(form).OfType<Label>().Any(l=>l.Text.Contains("assumes")),"Equipment assumptions paragraph removed");}using(var form=new CatalogForm(s)){Snapshot(form,Path.Combine(folder,"Catalog preview.png"));CheckLayout(form,check);}using(var form=new MainForm(true)){form.LoadTest(forecast,now);form.Size=form.MinimumSize;Snapshot(form,Path.Combine(folder,"Dashboard minimum preview.png"));check(!Walk(form).OfType<ScrollableControl>().Any(c=>c.AutoScroll),"Dashboard has no scrolling container");CheckLayout(form,check);check(Walk(form).OfType<Button>().Any(b=>b.AccessibleName=="Settings"),"Settings gear is available on the dashboard");}
        RunPlanningTests(s,forecast,now,check,folder);
    }
    static void RunPlanningTests(Settings s,Forecast forecast,DateTime now,Action<bool,string> check,string folder){
        var morning=new Night(s,forecast,s.Utc(new DateTime(2026,10,24,10,0,0)));check(s.Local(morning.Start).Date==new DateTime(2026,10,24),"Daytime after dawn selects the upcoming night, not the expired night");check(morning.Picks.Count>0,"Daytime planning still returns targets");var midnight=new Night(s,forecast,s.Utc(new DateTime(2026,10,25,2,0,0)));check(midnight.Start==morning.Start,"Before dawn retains the active observing night");check(midnight.Picks.Select(x=>x.Target.Name).SequenceEqual(morning.Picks.Select(x=>x.Target.Name)),"Targets remain identical across daytime and nighttime views of the same night");check(midnight.Picks.All(p=>p.Start>=midnight.Dark.First()&&p.Best<=midnight.Dark.Last()),"All shooting plans start no earlier than dark-sky time");check(midnight.Picks.Any(p=>p.Start<midnight.Now),"Full-night planning retains earlier windows instead of filtering by current time");
        var bad=new Forecast();bad.Hours=forecast.Hours.Select(h=>new Hour{Utc=h.Utc,Cloud=100,Rain=100,Temp=h.Temp,Wind=150}).ToList();bad.Seeing=forecast.Seeing.Select(h=>new Sky{Utc=h.Utc,Seeing=8}).ToList();var worse=new Night(s,bad,now,new DateTime(2026,10,24));var clear=new Forecast();clear.Hours=forecast.Hours.Select(h=>new Hour{Utc=h.Utc,Cloud=0,Rain=0,Temp=h.Temp,Wind=0}).ToList();clear.Seeing=forecast.Seeing.Select(h=>new Sky{Utc=h.Utc,Seeing=1}).ToList();var better=new Night(s,clear,now,new DateTime(2026,10,24));check(worse.Picks.Select(x=>x.Target.Name).SequenceEqual(better.Picks.Select(x=>x.Target.Name)),"Clouds, rain, wind and seeing cannot alter target ranking");check(worse.Picks.Select(x=>x.Best).SequenceEqual(better.Picks.Select(x=>x.Best)),"Shooting times are based on visibility rather than weather");var future=new Night(s,new Forecast(),now,new DateTime(2027,1,15));check(future.Picks.Count>0&&s.Local(future.Start).Date==new DateTime(2027,1,15),"Explicit future dates return targets without weather data");check(forecast.WeatherNote(new DateTime(2030,1,1)).Contains("range"),"Future weather outside coverage has an explicit range explanation");check(forecast.SeeingLabel(new DateTime(2030,1,1)).Contains("range"),"Future seeing outside coverage has an explicit range explanation");var offline=new Forecast{WeatherError="Connection failed",SeeingError="Connection failed"};check(offline.WeatherNote(now).Contains("offline")&&offline.SeeingLabel(now).Contains("offline"),"Service failures are distinguished from forecast range limits");
        using(var form=new MainForm(true)){form.LoadTest(forecast,s.Utc(new DateTime(2026,10,24,10,0,0)));Snapshot(form,Path.Combine(folder,"Morning planning preview.png"));check(!Walk(form).OfType<Label>().Any(l=>l.Text.Contains("No dark sky remaining")),"Morning dashboard no longer shows the expired-night empty state");check(Walk(form).OfType<DateTimePicker>().Count()==1,"Planning date can be selected on the dashboard");check(Walk(form).OfType<AppButton>().Any(b=>Convert.ToString(b.Tag)=="gear"&&b.Text==""),"Settings uses an unboxed drawn gear rather than a boxed text glyph");}
        using(var futureForm=new MainForm(true)){futureForm.LoadTest(forecast,now,new DateTime(2027,1,15));Snapshot(futureForm,Path.Combine(folder,"Future planning preview.png"));check(Walk(futureForm).Any(l=>l.Text.Contains("Beyond seeing forecast range")||(l.AccessibleName??"").Contains("Beyond seeing forecast range")),"Future dashboard explains seeing coverage while retaining target cards");}
        foreach(var form in new Form[]{new MainForm(true),new LocationForm(s),new EquipmentForm(s),new CatalogForm(s)})using(form){check(form.ShowIcon&&form.Icon!=null,form.Text+" has the NightLens window icon");foreach(var combo in Walk(form).OfType<ComboBox>().Where(c=>c.DrawMode==DrawMode.OwnerDrawFixed))check(combo.ItemHeight>=Math.Ceiling(combo.Font.GetHeight())+4,"Dropdown reserves enough height for glyph descenders");}
    }
    static void CheckLayout(Form form,Action<bool,string> check){foreach(var c in Walk(form).Where(c=>c.Visible&&(c is Button||c is TextBox||c is NumericUpDown||c is CheckBox||c is ComboBox))){var rect=form.RectangleToClient(c.RectangleToScreen(c.ClientRectangle));if(!form.ClientRectangle.Contains(rect))throw new Exception(form.Text+": clipped input "+c.Text+" at "+rect);}check(true,form.Text+" input controls fit within window");}
}
}



